const searchFields = ["mileage", "vin", "licensePlate","colorCode"];

for (const item of $input.all()) {
  const chatAnswers = item.json.chatAnswers || {};
  const missingFields = [];

  for (const field of searchFields) {
    if (
      !chatAnswers.hasOwnProperty(field) ||      // field not present
      chatAnswers[field] === null ||             // field is null
      chatAnswers[field] === "" ||               // empty string
      (field === "mileage" && (chatAnswers[field] === "0" || chatAnswers[field] === 0)) // special case: mileage is "0"
    ) {
      missingFields.push(field);
    }
  }

  item.json.missingFields = missingFields;
}

return $input.all();

const inputTexts = $('Open AI get details using images').all()

const calculateJSONObject = (text)=>{
  let jsonObject = {}
try {
    jsonObject = JSON.parse(text)

  if (jsonObject && jsonObject?.mileage) {
    const rawStr = String(jsonObject.mileage).toLowerCase().replace(/,/g, '');

    // ([\d\.]+)  -> Capture the numeric part (digits and decimal points)
    // \s* -> Match zero or more spaces
    // (km|mi)    -> Capture the unit (matches "km" or anything starting with "mi" like "mile", "miles")
    const match = rawStr.match(/([\d\.]+)\s*(km|mi)/);

    if (match) {
      const value = parseFloat(match[1]); // The number (e.g., 18552)
      const unit = match[2];              // The unit (e.g., "km" or "mi")

      if (unit.startsWith('mi')) {
        // Case: Miles -> Convert to KM (1 mile = 1.60934 km)
        jsonObject.mileage = Math.round(value * 1.60934);
      } else {
        // Case: KM -> Just assigning the number
        jsonObject.mileage = value;
      }
    }
  }

    // Ensure color key exists and trim whitespace
    if(jsonObject?.color){
        jsonObject.color = jsonObject.color.toString().trim()
    }

    // Optional: trim licensePlate
    if(jsonObject?.licensePlate){
        jsonObject.licensePlate = jsonObject.licensePlate.toString().trim()
    }

} catch(error){
    // fallback empty object
    jsonObject = {}
}
  return jsonObject
}
let finalJsonObject = {} 
inputTexts.forEach(inputText=>{
const text = inputText.json?.output?.[1]?.content?.[0]?.text || "{}"
  const objectData = calculateJSONObject(text)
  finalJsonObject = {
    ...finalJsonObject,
    ...objectData
  }

})

return finalJsonObject

