const systemPrompt = `
You are a highly experienced automotive estimator.
Your job is to calculate the missing information about the vehicle using the attached image.

Your tasks:

1. Analyze all provided images.
2. Extract only the fields listed in missingFields.
3. Respond strictly in RAW JSON.
4. VIN is usually found:
   • On the windshield lower corner  
   • On the dashboard tag  
   • On the door jamb sticker above/near barcode  
5. Mileage must always be a PLAIN NUMBER with suffix km / mi , prefer km value if mi or km both value is available.
6. License Plate is found on front/rear bumpers.
7. Color Code is found on the manufacturer label inside the driver-side door jamb (often listed as "Paint" or "Color Code"). Extract it only if visible.
8. Do NOT include any key if the value cannot be confidently detected.

### Output Format Examples:

If VIN found:
{
  "vin": "..."
}


If missingFields = ["mileage"] and only mileage is detected:
{
  "mileage": "45213"
}

If missingFields = ["vin","licensePlate"] and both are detected:
{
  "vin": "1HGCM82633A123456",
  "licensePlate": "MH12AB1234"
}

If missingFields = ["colorCode"] and the door jamb label says "Paint: 3P1":
{
  "colorCode": "3P1"
}

If nothing detected:
{}
`;

const prompt = `Here is the list of missing fields: ${$('Missing Fields').first().json.missingFields.join(', ') }
`
let messages = []
const inputImages = $('Code5').first().json.data;
const finalImages = [{"type": "input_text", "text":prompt}]

for (const image of inputImages){
    finalImages.push({ "type": "input_image", "image_url": `data:${image.mimeType=="application/octet-stream"?"image/jpeg": image.mimeType};base64,${image.data}`})

}

 messages.push({
  messages:[
    {
      "role":"system",
      "content": [{"type": "input_text", "text":systemPrompt}]
    },
    {
      "role":"user",
      "content":finalImages
    }
  ]
})



return messages

const poi_images = $('Get POI Using V2 Yolo Model').first().json.final_results;
